var program;

function setup() {
 pixelDensity(1);
  createCanvas(500, 500,WEBGL);
  // createCanvas(windowWidth, windowHeight,WEBGL);
  gl=this.canvas.getContext('webgl');
	rectMode(CENTER);
  noStroke();
  fill(1);
  program = createShader(vert,frag);
	}

function draw() {
  shader(program);
  background(0);
	program.setUniform('u_resolution',[width,height]);
	program.setUniform('u_time',millis()/1000);
  rect(0,0,width,height);
}


var vert=`
		#ifdef GL_ES
		precision highp float;
    precision highp int;
    #endif
		#extension GL_OES_standard_derivatives : enable

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    //uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      // var_vertPos      = aPosition;
      // var_vertCol      = aVertexColor;
      // var_vertNormal   = aNormal;
      // var_vertTexCoord = aTexCoord;
    }
`;

var frag=`

#ifdef GL_ES
precision mediump float;
#endif

#define PI 3.14159265359
#define TWO_PI 6.28318530718

uniform vec2    u_resolution;
uniform float   u_time;

vec3 random3(vec3 c) {
    float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
    vec3 r;
    r.z = fract(512.0*j);
    j *= .125;
    r.x = fract(512.0*j);
    j *= .125;
    r.y = fract(512.0*j);
    return r-0.5;
}

const float F3 =  0.3333333;
const float G3 =  0.1666667;
float snoise(vec3 p) {

    vec3 s = floor(p + dot(p, vec3(F3)));
    vec3 x = p - s + dot(s, vec3(G3));

    vec3 e = step(vec3(0.0), x - x.yzx);
    vec3 i1 = e*(1.0 - e.zxy);
    vec3 i2 = 1.0 - e.zxy*(1.0 - e);

    vec3 x1 = x - i1 + G3;
    vec3 x2 = x - i2 + 2.0*G3;
    vec3 x3 = x - 1.0 + 3.0*G3;

    vec4 w, d;

    w.x = dot(x, x);
    w.y = dot(x1, x1);
    w.z = dot(x2, x2);
    w.w = dot(x3, x3);

    w = max(0.6 - w, 0.0);

    d.x = dot(random3(s), x);
    d.y = dot(random3(s + i1), x1);
    d.z = dot(random3(s + i2), x2);
    d.w = dot(random3(s + 1.0), x3);

    w *= w;
    w *= w;
    d *= w;

    return dot(d, vec4(52.0));
}


void main(void) {
    vec4 color = vec4(vec3(0.0), 1.0);
    vec2 pixel = 1.0/u_resolution.xy;
    vec2 st = gl_FragCoord.xy * pixel;


    vec2 pointR[10];
    vec2 pointG[10];
    vec2 pointB[10];
    float t_offset = .02;
    for(int i = 0; i < 10; i++){
        pointR[i] = vec2(snoise(vec3(464.,823.+float(i),u_time*.2)),
                        snoise(vec3(856.,123.+float(i),u_time*.2)))+.5;
    }
     for(int i = 0; i < 10; i++){
        pointG[i] = vec2(snoise(vec3(464.,823.+float(i),u_time*.2-t_offset)),
                        snoise(vec3(856.,123.+float(i),u_time*.2-t_offset)))+.5;
    }
     for(int i = 0; i < 10; i++){
        pointB[i] = vec2(snoise(vec3(464.,823.+float(i),u_time*.2-t_offset*2.)),
                        snoise(vec3(856.,123.+float(i),u_time*.2-t_offset*2.)))+.5;
    }


    // metaball (BEAUTIFUL~~
    float charge = 1.5;
    float metaballR = .0;
    for(int i = 0; i < int(floor(10.)); i++){
        metaballR += charge/(distance(st,pointR[i]));
    }
    metaballR *= .015;
    float metaballG = .0;
    for(int i = 0; i < int(floor(10.)); i++){
        metaballG += charge/(distance(st,pointG[i]));
    }
    metaballG *= .015;
    float metaballB = .0;
    for(int i = 0; i < int(floor(10.)); i++){
        metaballB += charge/(distance(st,pointB[i]));
    }
    metaballB *= .015;

    // color.r += smoothstep(.9,.91, metaballR);
    // color.g += smoothstep(.9,.91, metaballG);
    // color.b += smoothstep(.9,.91, metaballB);

    color.r += metaballR;
    color.g += metaballG;
    color.b += metaballB;


    gl_FragColor = color;
}
`

